class Node {
  prev: Node | null = null;
  next: Node | null = null;
  constructor(public key: number, public val: number) {}
}

class LRUCache {
  private map = new Map<number, Node>();
  private head = new Node(0, 0); // most recent side
  private tail = new Node(0, 0); // least recent side

  constructor(private capacity: number) {
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  private unlink(n: Node): void {
    n.prev!.next = n.next;
    n.next!.prev = n.prev;
  }

  private pushFront(n: Node): void {
    n.next = this.head.next;
    n.prev = this.head;
    this.head.next!.prev = n;
    this.head.next = n;
  }

  get(key: number): number {
    const n = this.map.get(key);
    if (!n) return -1;
    this.unlink(n);
    this.pushFront(n);
    return n.val;
  }

  put(key: number, value: number): void {
    const n = this.map.get(key);
    if (n) {
      n.val = value;
      this.unlink(n);
      this.pushFront(n);
      return;
    }
    if (this.map.size === this.capacity) {
      const lru = this.tail.prev!;
      this.unlink(lru);
      this.map.delete(lru.key);
    }
    const fresh = new Node(key, value);
    this.map.set(key, fresh);
    this.pushFront(fresh);
  }
}

